package me.cryo.zombierool.scripting;
import java.nio.file.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.nbt.*;
public final class LuaWorkbench {
 public static Path directory(ServerPlayer p)throws Exception{var root=me.cryo.zombierool.util.WorldZombieroolPaths.getScriptsDir(p.serverLevel()).toPath();if(Files.isSymbolicLink(root))throw new IllegalArgumentException("Script directory cannot be a symbolic link");Files.createDirectories(root);return root.toRealPath();}
 public static Path file(ServerPlayer p,String name)throws Exception{if(!name.matches("[A-Za-z0-9_-]{1,64}\\.lua"))throw new IllegalArgumentException("Use a name like main.lua (letters, numbers, underscores)");var root=directory(p);var file=root.resolve(name);if(Files.isSymbolicLink(file)||Files.exists(file)&&!file.toRealPath().startsWith(root))throw new IllegalArgumentException("Script outside map directory");if(!Files.exists(file)){var legacy=p.server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("zr_scripts").resolve(name);if(Files.isRegularFile(legacy)&&!Files.isSymbolicLink(legacy)&&!Files.isSymbolicLink(legacy.getParent()))return legacy;}return file;}
 public static String hash(String text)throws Exception{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 public static CompoundTag request(ServerPlayer p,String action,String name,String code,String version){var out=new CompoundTag();out.putString("action",action);out.putString("name",name);try{
  if(!p.hasPermissions(2))throw new IllegalArgumentException("Operator permission required");
  if(action.startsWith("actor_"))return MapActorAuthoring.request(p,action,name,code,version);
  if(code.length()>120000)throw new IllegalArgumentException("Script exceeds 120000 characters");
  if(action.equals("list")){var list=new ListTag();for(var f:me.cryo.zombierool.util.WorldZombieroolPaths.scripts(p.serverLevel()))if(f.getName().matches("[A-Za-z0-9_-]{1,64}\\.lua"))list.add(StringTag.valueOf(f.getName()));out.put("files",list);}
  else if(action.equals("console")){var list=new ListTag();LuaScriptManager.console().forEach(s->list.add(StringTag.valueOf(s)));out.put("lines",list);}
  else if(action.equals("validate")){out.putString("message",LuaScriptManager.validate(code));}
  else if(action.equals("reload")){LuaScriptManager.loadScripts(p.serverLevel());out.putString("message","Reloaded scripts. Runtime variables and timers reset.");}
  else if(action.equals("run")){if(!LuaScriptManager.validate(code).equals("OK"))throw new IllegalArgumentException(LuaScriptManager.validate(code));if(!LuaScriptManager.ready(p.serverLevel()))LuaScriptManager.loadScripts(p.serverLevel());out.putString("message",LuaScriptManager.executeString(code));}
  else if(action.equals("read")){var f=file(p,name);if(Files.size(f)>480000)throw new IllegalArgumentException("File too large");var text=Files.readString(f);if(text.length()>120000)throw new IllegalArgumentException("File too large");out.putString("code",text);out.putString("version",hash(text));}
  else if(action.equals("save")){var f=file(p,name);String diagnostic=LuaScriptManager.validate(code);if(!diagnostic.equals("OK"))throw new IllegalArgumentException(diagnostic);if(Files.exists(f)){if(!hash(Files.readString(f)).equals(version))throw new IllegalArgumentException("File changed on disk: reopen it before saving");Path history=directory(p).resolve(".history");Files.createDirectories(history);if(Files.isSymbolicLink(history))throw new IllegalArgumentException("History directory cannot be a symbolic link");Files.copy(f,history.resolve(name+"."+System.currentTimeMillis()+".bak"));}else if(!version.isEmpty())throw new IllegalArgumentException("File was removed on disk");var temp=Files.createTempFile(directory(p),"edit-",".tmp");Files.writeString(temp,code);try{Files.move(temp,f,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,f,StandardCopyOption.REPLACE_EXISTING);}out.putString("version",hash(code));out.putString("message","Saved (not executed)");}
  else throw new IllegalArgumentException("Unknown editor action");
  out.putBoolean("success",true);
 }catch(Exception e){out.putBoolean("success",false);out.putString("message",String.valueOf(e.getMessage()));}return out;}
 private static com.google.gson.JsonArray guide(){try(var in=LuaWorkbench.class.getClassLoader().getResourceAsStream("assets/zombierool/"+(net.minecraft.locale.Language.getInstance().getOrDefault("scripting.zombierool.help_language").equals("fr")?"lua-api-guide_fr_fr.json":"lua-api-guide.json"))){if(in==null)return new com.google.gson.JsonArray();return com.google.gson.JsonParser.parseReader(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray();}catch(Exception e){return new com.google.gson.JsonArray();}}
 public static java.util.List<String> reference(String query){var result=new java.util.ArrayList<String>();if(query.isBlank())result.add("HOW TO START\n1. Guided: choose an event, condition and actions.\n2. Insert the rule into Code.\n3. Check, Save, then Reload to activate saved scripts.\nRun executes the current buffer immediately.\n\nSearch a method or topic below: atmosphere, voice, points, timer...");for(var entry:guide()){var row=entry.getAsJsonObject();String text="["+row.get("category").getAsString()+"] "+row.get("signature").getAsString()+"\n"+row.get("description").getAsString();String example=row.get("example").getAsString();if(!example.isBlank())text+="\nExample:\n"+example;if(text.toLowerCase(java.util.Locale.ROOT).contains(query.toLowerCase(java.util.Locale.ROOT)))result.add(text);}if(result.isEmpty())result.add("No match. Try atmosphere, points, voice or timer.");return result;}
 public static String example(String query){if(query.isBlank())return "";for(var entry:guide()){var row=entry.getAsJsonObject();if(((row.has("name")?row.get("name").getAsString():row.get("signature").getAsString())+" "+row.get("category").getAsString()+" "+row.get("description").getAsString()).toLowerCase(java.util.Locale.ROOT).contains(query.toLowerCase(java.util.Locale.ROOT))&&!row.get("example").getAsString().isBlank())return row.get("example").getAsString();}return "";}
}
